package main

import (
	"fmt"
	"path"
	"sort"
	"strings"
)

// sectionLines renders a package's codemap section as comment lines (each prefixed with //), ready for replaceSection.
//
// Notes:
//   - One block per file in name order, then one line per function: its signature and nothing else, so the section is
//     a pure function of the code.
func sectionLines(p Pkg) []string {
	out := []string{
		"// " + heading,
		"//",
		"// Generated by `go run ./cmd/codemap` from the code; do not edit by hand. Each file lists its function and",
		"// method signatures in source order.",
		"//",
	}
	last := ""
	for _, f := range p.Funcs {
		if f.File != last {
			if last != "" {
				out = append(out, "//")
			}
			out = append(out, "//\t"+f.File)
			last = f.File
		}
		out = append(out, "//\t  "+f.Sig)
	}
	return out
}

// codemapMD builds CODEMAP.md: a directory tree, then each package's section copied from its doc.go.
//
// Notes:
//   - sections is keyed by package Dir and holds the section lines read back from the generated doc.go text.
func codemapMD(module string, pkgs []Pkg, sections map[string][]string) string {
	var b strings.Builder
	b.WriteString("# CODEMAP\n\n")
	b.WriteString("Generated by `go run ./cmd/codemap`; do not edit by hand. Every package section below is copied from the\n")
	b.WriteString("`# Codemap (auto-generated)` section of that package's `doc.go`, which is built from the code.\n\n")
	b.WriteString("## Directory tree\n\n```text\n")
	b.WriteString(tree(path.Base(module), pkgs))
	b.WriteString("```\n")
	for _, p := range pkgs {
		fmt.Fprintf(&b, "\n## %s\n\n`%s`\n\n```text\n", dirTitle(p), p.ImportPath)
		b.WriteString(strings.Join(codeBlock(sections[p.Dir]), "\n"))
		b.WriteString("\n```\n")
	}
	return b.String()
}

// dirTitle is the heading text for a package in CODEMAP.md.
//
// Notes: none.
func dirTitle(p Pkg) string {
	if p.Dir == "." {
		return "(root) package " + p.Name
	}
	return p.Dir + " (package " + p.Name + ")"
}

type node struct {
	name     string
	children map[string]*node
}

// tree draws the module's directories and non-test Go files as a box-drawing tree.
//
// Notes:
//   - Within a directory, files come first, then subdirectories, each alphabetical.
func tree(rootName string, pkgs []Pkg) string {
	root := &node{name: rootName + "/", children: map[string]*node{}}
	add := func(parts []string, isDir bool) {
		n := root
		for i, part := range parts {
			label := part
			if isDir || i < len(parts)-1 {
				label += "/"
			}
			c, ok := n.children[label]
			if !ok {
				c = &node{name: label, children: map[string]*node{}}
				n.children[label] = c
			}
			n = c
		}
	}
	for _, p := range pkgs {
		var dir []string
		if p.Dir != "." {
			dir = strings.Split(p.Dir, "/")
		}
		for _, f := range p.Files {
			add(append(append([]string{}, dir...), f), false)
		}
	}
	var b strings.Builder
	b.WriteString(root.name + "\n")
	var walk func(n *node, prefix string)
	walk = func(n *node, prefix string) {
		names := make([]string, 0, len(n.children))
		for k := range n.children {
			names = append(names, k)
		}
		// files first, then directories, each alphabetical
		sort.Slice(names, func(i, j int) bool {
			di, dj := strings.HasSuffix(names[i], "/"), strings.HasSuffix(names[j], "/")
			if di != dj {
				return !di
			}
			return names[i] < names[j]
		})
		for i, k := range names {
			branch, next := "├── ", "│   "
			if i == len(names)-1 {
				branch, next = "└── ", "    "
			}
			b.WriteString(prefix + branch + k + "\n")
			walk(n.children[k], prefix+next)
		}
	}
	walk(root, "")
	return b.String()
}
